#include <bits/stdc++.h>
using namespace std;
const int N=2e5+5, mod=10007;
long long n, w[200005], s[N], mx[N], ans1, ans2; 
vector<int> e[200005];
void dfs(int u, int fa){
	long long sum = 0, Max = 0;
	for (int i:e[u]) {
		if (i==fa)
			continue;
		dfs(i, u);
		s[u]=(s[u]+w[i])%mod;
		mx[u]=max(mx[u], w[i]);
		ans2=(ans2+w[u]*s[i]%mod+w[i]*sum%mod)%mod;
		ans1=max({ans1, w[u]*mx[i], w[i]*Max});
		sum=(sum+w[i])%mod;
		Max=max(Max, w[i]);
	}
}
int main () {
	cin >> n;
	for (int i=1, u, v; i<n; ++i)
		cin >> u >> v,
		e[u].push_back(v),
		e[v].push_back(u);
	for (int i=1; i<=n; ++i)
		cin >> w[i];
	dfs(1, 1);
	cout << ans1 << ' ' << 2*ans2%mod;
	return 0;
}
